{
  "predictors": [
    {
      "name": "Customer Concentration",
      "construction": "Calculate the percentage of sales derived from a firm's major customers. Use annual report disclosures.",
      "rationale": "Firms with high customer concentration may face higher business risks.",
      "higher_returns_for": "Firms with low customer concentration"
    },
    {
      "name": "Employee Satisfaction",
      "construction": "Compute an index based on employee reviews from surveys. Use external survey data if available.",
      "rationale": "Firms with satisfied employees may have better productivity and lower staff turnover.",
      "higher_returns_for": "Firms with high employee satisfaction"
    },
    {
      "name": "Patent Quality",
      "construction": "Count the number of times a firm's patents are cited by other patents. Use US Patent and Trademark Office data.",
      "rationale": "Firms with high quality patents may enjoy greater competitive advantages.",
      "higher_returns_for": "Firms with high patent quality"
    },
    {
      "name": "Advertising Intensity",
      "construction": "Compute a firm's advertising expenditure as a percentage of its sales. Use data from annual reports.",
      "rationale": "Firms with high advertising intensity may have strong brand recognition.",
      "higher_returns_for": "Firms with high advertising intensity"
    },
    {
      "name": "Innovation Efficiency",
      "construction": "Calculate a firm's research and development expenditure as a percentage of its patent counts. Use data from annual reports and US Patent and Trademark Office.",
      "rationale": "Firms that efficiently convert R&D into patents may have superior innovation capabilities.",
      "higher_returns_for": "Firms with high innovation efficiency"
    },
    {
      "name": "Environmental Responsibility",
      "construction": "Construct a score based on a firm's environmental practices. Use data from sustainability reports or external ESG ratings agencies.",
      "rationale": "Firms with strong environmental responsibility may face less regulatory risks.",
      "higher_returns_for": "Firms with high environmental responsibility"
    },
    {
      "name": "Product Diversity",
      "construction": "Count the number of unique products or services a firm offers. Use firm's annual reports or product catalogs.",
      "rationale": "Firms with diverse products may have lower business risks.",
      "higher_returns_for": "Firms with high product diversity"
    },
    {
      "name": "Executive Gender Diversity",
      "construction": "Calculate the percentage of a firm's executives that are women. Use data from annual reports or proxy statements.",
      "rationale": "Firms with gender diverse leadership may have more balanced decision making.",
      "higher_returns_for": "Firms with high executive gender diversity"
    },
    {
      "name": "Supply Chain Complexity",
      "construction": "Compute an index based on the number of suppliers and geographical spread of a firm's supply chain. Use data from annual reports or supplier disclosures.",
      "rationale": "Firms with complex supply chains may face higher operational risks.",
      "higher_returns_for": "Firms with low supply chain complexity"
    },
    {
      "name": "Health and Safety Record",
      "construction": "Calculate a score based on a firm's recorded incidents and accidents. Use data from Occupational Safety and Health Administration (OSHA).",
      "rationale": "Firms with strong health and safety records may face lower litigation risks.",
      "higher_returns_for": "Firms with strong health and safety records"
    }
  ]
}
